mapper.select:
SELECT transaction_id, tenant_id, warehouse_id, seller_sku, transaction_type, quantity,
       before_on_hand, before_reserved, after_on_hand, after_reserved,
       reference_type, reference_id, remark, created_at
FROM wms_inventory_transaction
WHERE tenant_id = #{tenantId}

    AND warehouse_id = #{warehouseId}


    AND seller_sku = #{sellerSku}

ORDER BY created_at DESC, transaction_id DESC
